#!/usr/bin/env python3
"""Assumptions TTL check: every working assumption of an autonomous agent carries a source and an expiry.

Distilled from the Peshkov «Agentic Discipline» rules and the Lane Pilot hygiene of learnings.md:
no number from memory, every assumption has a source and a TTL, an expired assumption must be
re-verified before it is used again.
  expired       ttl date < as_of                                  -> error
  expiring      ttl within warn_days                              -> warning
  no_ttl        neither ttl nor created + default_ttl_days         -> error
  no_source     no source                                         -> warning (error if it holds a number)
  number_from_memory   a number in the text and no source         -> error

Input: JSON {"as_of", "warn_days": 7, "default_ttl_days": 30,
             "assumptions": [{"id", "text", "source", "ttl" | "created"}]}
   or  --markdown learnings.md with lines like
       - [A-12] Конверсия лендинга 3.1% (source: metrika 2026-10; ttl: 2026-11-30)
       - [A-13] Клиент не меняет цены до января (created: 2026-11-01)
Output JSON: items[] {id, status, ttl, days_left, issues[]}, counts{}, verdict (pass|fail).
"""
import argparse
import json
import re
import sys
from datetime import date, timedelta

NAME = "check_assumptions_ttl.py"
VERSION = "1.0.0"
LINE_RE = re.compile(r"^\s*[-*]\s*\[(?P<id>[^\]]+)\]\s*(?P<text>.*?)\s*(\((?P<meta>[^()]*)\))?\s*$")
NUM_RE = re.compile(r"\d+(?:[.,]\d+)?\s*%?")


class Parser(argparse.ArgumentParser):
    def error(self, message):
        fail("usage", message, 2)


def emit(obj):
    sys.stdout.write(json.dumps(obj, ensure_ascii=False, sort_keys=True, indent=2) + "\n")


def fail(code, message, rc=1):
    emit({"ok": False, "script": NAME, "version": VERSION, "error": {"code": code, "message": str(message)}})
    sys.exit(rc)


def load_input(args, fixture):
    if args.fixture:
        return fixture
    if args.markdown:
        try:
            with open(args.markdown, encoding="utf-8") as fh:
                return {"assumptions": parse_markdown(fh.read())}
        except OSError as exc:
            fail("bad_input", "%s: %s" % (args.markdown, exc), 2)
    if not args.input:
        fail("no_input", "pass --input FILE.json, --markdown FILE.md or --fixture", 2)
    try:
        if args.input == "-":
            return json.load(sys.stdin)
        with open(args.input, encoding="utf-8") as fh:
            return json.load(fh)
    except (OSError, ValueError) as exc:
        fail("bad_input", "%s: %s" % (args.input, exc), 2)


def parse_markdown(text):
    items = []
    for line in text.splitlines():
        m = LINE_RE.match(line)
        if not m:
            continue
        item = {"id": m.group("id").strip(), "text": m.group("text").strip()}
        for part in (m.group("meta") or "").split(";"):
            if ":" in part:
                k, v = part.split(":", 1)
                item[k.strip().lower()] = v.strip()
        items.append(item)
    return items


FIXTURE = {"as_of": "2026-11-11", "warn_days": 7, "default_ttl_days": 30, "assumptions": parse_markdown(
    "- [A-1] Конверсия лендинга 3.1% (source: metrika 2026-10; ttl: 2026-11-30)\n"
    "- [A-2] Средний чек 4 900 руб (ttl: 2026-12-31)\n"
    "- [A-3] Клиент не меняет цены до января (source: письмо клиента; created: 2026-10-01)\n"
    "- [A-4] Сезонный спад в декабре (source: YoY Метрика; ttl: 2026-11-15)\n"
    "- [A-5] Бренд-запросы растут\n")}


def compute(data, args):
    as_of = date.fromisoformat(args.as_of or data.get("as_of") or "")
    warn = int(data.get("warn_days", 7))
    default_ttl = data.get("default_ttl_days", 30)
    rows, counts = [], {}
    items = data["assumptions"]
    if not items:
        raise ValueError("no assumptions found")
    for a in items:
        issues, ttl = [], None
        if a.get("ttl"):
            ttl = date.fromisoformat(str(a["ttl"]))
        elif a.get("created") and default_ttl is not None:
            ttl = date.fromisoformat(str(a["created"])) + timedelta(days=int(default_ttl))
        has_num = bool(NUM_RE.search(str(a.get("text") or "")))
        src = str(a.get("source") or "").strip()
        if ttl is None:
            issues.append({"code": "no_ttl", "level": "error"})
        if not src:
            issues.append({"code": "number_from_memory" if has_num else "no_source", "level": "error" if has_num else "warning"})
        days_left = (ttl - as_of).days if ttl else None
        if days_left is not None and days_left < 0:
            issues.append({"code": "expired", "level": "error"})
        elif days_left is not None and days_left <= warn:
            issues.append({"code": "expiring", "level": "warning"})
        status = "invalid" if any(i["code"] in ("no_ttl", "number_from_memory") for i in issues) else (
            "expired" if any(i["code"] == "expired" for i in issues) else (
                "expiring" if any(i["level"] == "warning" for i in issues) else "ok"))
        counts[status] = counts.get(status, 0) + 1
        rows.append({"id": a.get("id"), "text": a.get("text"), "source": src or None,
                     "ttl": ttl.isoformat() if ttl else None, "days_left": days_left, "status": status, "issues": issues})
    errors = sum(1 for r in rows for i in r["issues"] if i["level"] == "error")
    return {"as_of": as_of.isoformat(), "items": rows, "counts": counts, "errors": errors,
            "verdict": "fail" if errors else "pass"}


def main():
    ap = Parser(prog=NAME, description="Check TTL and sources of agent assumptions (JSON or learnings.md).")
    ap.add_argument("--input", help="JSON input file, - for stdin")
    ap.add_argument("--markdown", help="learnings.md style file with '- [ID] text (source: ..; ttl: ..)' lines")
    ap.add_argument("--fixture", action="store_true", help="run on the built-in offline sample")
    ap.add_argument("--as-of", help="check date YYYY-MM-DD (required for --markdown unless in input)")
    ap.add_argument("--strict", action="store_true", help="exit 3 when verdict is fail")
    args = ap.parse_args()
    data = load_input(args, FIXTURE)
    try:
        result = compute(data, args)
    except (KeyError, TypeError, ValueError) as exc:
        fail("invalid_data", "%s: %s" % (type(exc).__name__, exc), 2)
    emit({"ok": True, "script": NAME, "version": VERSION, **result})
    if args.strict and result["verdict"] == "fail":
        sys.exit(3)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""curriculum_lint.py — copy, secret & watermark lint for distilled course/book material (lp.curriculum-ingest).

Checks distilled .md/.json/.jsonl/.txt drafts or inline items for:
  * quoted spans longer than --max-quote-words (default 25) words;
  * resale / leak watermark tokens (Latin and Cyrillic);
  * leaked API keys / tokens / credentials;
  * 12-word shingle verbatim overlap against --sources above --max-shingle-overlap (default 0.20).
Supports both --fixture / --input FILE|- (common verified-script contract) and --atoms / --questions / --sources
(plugin-db-and-sp-executors-spec §3.2). Standard library only; deterministic JSON output.
"""
import argparse
import json
import os
import re
import sys
import tempfile
from pathlib import Path

SCRIPT = "curriculum_lint.py"
VERSION = "1.0.0"

QUOTE_RE = re.compile(r"«([^»]{1,4000})»|\"([^\"\n]{1,4000})\"|“([^”]{1,4000})”")
WATERMARK_PATTERNS = [
    re.compile("skl" + r"ad\s*chik", re.I),
    re.compile("скл" + r"ад\s*чик", re.I),
    re.compile("sliv" + r"y?\s*sklad", re.I),
    re.compile(r"скачано\s+с", re.I),
    re.compile(r"слив\s+курс", re.I),
    re.compile("course" + r"hunter", re.I),
    re.compile("share" + r"wood", re.I),
]
SECRET_PATTERNS = [
    re.compile(r"\bsk-[A-Za-z0-9]{20,}\b"),
    re.compile(r"\bAIza[0-9A-Za-z_-]{30,}\b"),
    re.compile(r"\by0_[A-Za-z0-9_-]{20,}\b"),
    re.compile(r"\bghp_[A-Za-z0-9]{25,}\b"),
]
EXT = {".md", ".json", ".jsonl", ".txt"}
SHINGLE = 12


def emit(payload, code=0):
    sys.stdout.write(json.dumps(payload, ensure_ascii=False, sort_keys=True) + "\n")
    return code


def fail(code_name, message, exit_code=2):
    return emit(
        {
            "error": {"code": code_name, "message": str(message)},
            "ok": False,
            "script": SCRIPT,
            "version": VERSION,
        },
        exit_code,
    )


def words(text):
    return re.findall(r"[\w’'-]+", (text or "").lower())


def shingles(text):
    w = words(text)
    if len(w) < SHINGLE:
        return set()
    return {" ".join(w[i : i + SHINGLE]) for i in range(0, len(w) - SHINGLE + 1)}


def collect_paths(paths):
    out = []
    for raw in paths:
        p = Path(raw)
        if p.is_dir():
            for child in sorted(p.rglob("*")):
                if child.is_file() and child.suffix in EXT and child.name != "curriculum_lint.report.json":
                    out.append(child)
        elif p.is_file():
            out.append(p)
        else:
            raise FileNotFoundError(str(p))
    return out


def collect_source_files(paths):
    out = []
    for raw in paths:
        p = Path(raw)
        if p.suffix == ".json" and p.is_file():
            data = json.loads(p.read_text(encoding="utf-8"))
            stack = [data]
            found = []
            while stack:
                cur = stack.pop()
                if isinstance(cur, dict):
                    stack.extend(cur.values())
                elif isinstance(cur, list):
                    stack.extend(cur)
                elif isinstance(cur, str) and len(cur) < 1024 and Path(cur).exists():
                    found.append(cur)
            if found:
                out.extend(collect_paths(found))
        else:
            out.extend(collect_paths([p]))
    return out


def lint_documents(docs, max_words=25, source_texts=(), max_overlap=0.2, report_path=None):
    src_shingles = set()
    for st in source_texts:
        src_shingles |= shingles(st)

    long_quotes = []
    marks = []
    secrets = []
    runs = []

    for doc in docs:
        label = str(doc["name"])
        text = str(doc["text"])
        is_json = label.endswith(".json")
        if not is_json:
            for m in QUOTE_RE.finditer(text):
                span = next(g for g in m.groups() if g is not None)
                n = len(span.split())
                if n > max_words:
                    long_quotes.append({"file": label, "start": span[:60], "words": n})
        for rx in WATERMARK_PATTERNS:
            for m in rx.finditer(text):
                marks.append({"file": label, "match": m.group(0)})
        for rx in SECRET_PATTERNS:
            for m in rx.finditer(text):
                secrets.append({"file": label, "prefix": m.group(0)[:8] + "***"})
        if src_shingles:
            own = shingles(text)
            hit = sorted(own & src_shingles)
            if hit and own:
                share = round(len(hit) / float(len(own)), 4)
                runs.append(
                    {
                        "example": hit[0],
                        "file": label,
                        "over_threshold": share > max_overlap,
                        "share": share,
                        "shared_12gram_count": len(hit),
                    }
                )

    violations_count = (
        len(long_quotes)
        + len(marks)
        + len(secrets)
        + sum(1 for r in runs if r["over_threshold"])
    )
    verdict = "pass" if violations_count == 0 else "block"
    res = {
        "files": len(docs),
        "long_quotes": long_quotes,
        "ok": True,
        "pass": violations_count == 0,
        "report_path": report_path,
        "script": SCRIPT,
        "secrets": secrets,
        "verbatim_runs": runs,
        "verdict": verdict,
        "version": VERSION,
        "violations": violations_count,
        "watermarks": marks,
    }
    if report_path:
        parent = os.path.dirname(os.path.abspath(report_path))
        if parent:
            os.makedirs(parent, exist_ok=True)
        with open(report_path, "w", encoding="utf-8") as wf:
            wf.write(json.dumps(res, ensure_ascii=False, indent=2, sort_keys=True) + "\n")
    return res


def fixture_payload():
    return {
        "documents": [
            {
                "name": "mkt-unit-economics.md",
                "text": (
                    "# Unit Economics Gate\n\n"
                    "Формула: CAC = spend / paid_orders. Не отключать когорту до P90 lag платежа.\n"
                    "Правило: «Короткая проверенная цитата из шести слов».\n"
                ),
            },
            {
                "name": "questions-sample.md",
                "text": (
                    "## Q-MKT-001\n"
                    "Проверить долю неразмеченного трафика и сходимость кликов с CRM-лидами на окне 14 дней.\n"
                ),
            },
        ],
        "max_quote_words": 25,
        "max_shingle_overlap": 0.2,
        "sources": [
            "Сырой конспект лекции про сквозную аналитику и когортный анализ платежей в воронке продаж за месяц."
        ],
    }


def selftest():
    with tempfile.TemporaryDirectory() as tmp:
        t = Path(tmp)
        (t / "good.md").write_text(
            "Формула: CAC = spend / new_customers. «Короткая цитата из пяти слов».",
            encoding="utf-8",
        )
        wm_token = "skl" + "ad chik"
        (t / "bad.md").write_text(
            "«" + " ".join(["слово"] * 30) + "» и метка " + wm_token,
            encoding="utf-8",
        )
        (t / "src.txt").write_text(" ".join("w%d" % i for i in range(40)), encoding="utf-8")
        (t / "copy.md").write_text(" ".join("w%d" % i for i in range(30)), encoding="utf-8")

        good = lint_documents(
            [{"name": str(t / "good.md"), "text": (t / "good.md").read_text(encoding="utf-8")}],
            25,
            [(t / "src.txt").read_text(encoding="utf-8")],
        )
        bad = lint_documents(
            [{"name": str(t / "bad.md"), "text": (t / "bad.md").read_text(encoding="utf-8")}],
            25,
        )
        copy_res = lint_documents(
            [{"name": str(t / "copy.md"), "text": (t / "copy.md").read_text(encoding="utf-8")}],
            25,
            [(t / "src.txt").read_text(encoding="utf-8")],
            0.2,
        )
        ok = (
            good["pass"]
            and (not bad["pass"])
            and bad["violations"] == 2
            and copy_res["violations"] == 1
        )
        return {
            "bad_findings": bad["violations"],
            "good_pass": good["pass"],
            "ok": ok,
            "script": SCRIPT,
            "selftest": "curriculum_lint",
            "verdict": "pass" if ok else "block",
            "version": VERSION,
        }


class JsonArgParser(argparse.ArgumentParser):
    def error(self, message):
        raise ValueError(message)


def load_json_source(src):
    if src == "-":
        raw = sys.stdin.read()
    else:
        with open(src, "r", encoding="utf-8") as f:
            raw = f.read()
    if not raw.strip():
        raise ValueError("empty JSON input")
    return json.loads(raw)


def main(argv):
    if not argv:
        return fail("no_input", "pass --fixture, --input FILE|-, or --atoms/--questions/--dir/--file", 2)
    if "-h" in argv or "--help" in argv:
        ap_help = argparse.ArgumentParser(description=__doc__.splitlines()[0])
        ap_help.add_argument("--fixture", action="store_true", help="run built-in deterministic fixture")
        ap_help.add_argument("--input", help="JSON file path or - for stdin ({documents, sources?, max_quote_words?, max_shingle_overlap?})")
        ap_help.add_argument("--atoms", action="append", default=[], help="atoms file or folder (repeatable)")
        ap_help.add_argument("--questions", action="append", default=[], help="questions file or folder (repeatable)")
        ap_help.add_argument("--sources", action="append", default=[], help="source texts: folder, file, or JSON inventory")
        ap_help.add_argument("--dir", action="append", default=[], help="alias: folder of distilled files")
        ap_help.add_argument("--file", action="append", default=[], help="alias: single file")
        ap_help.add_argument("--source", action="append", default=[], help="alias of --sources")
        ap_help.add_argument("--max-quote-words", type=int, default=25)
        ap_help.add_argument("--max-shingle-overlap", type=float, default=0.2)
        ap_help.add_argument("--report", help="where to write the full report JSON")
        ap_help.add_argument("--strict", action="store_true", help="exit 3 when verdict is block")
        ap_help.add_argument("--selftest", action="store_true", help="run self-test suite")
        ap_help.print_help()
        return 0

    ap = JsonArgParser(add_help=False)
    ap.add_argument("--fixture", action="store_true")
    ap.add_argument("--input")
    ap.add_argument("--atoms", action="append", default=[])
    ap.add_argument("--questions", action="append", default=[])
    ap.add_argument("--sources", action="append", default=[])
    ap.add_argument("--dir", action="append", default=[])
    ap.add_argument("--file", action="append", default=[])
    ap.add_argument("--source", action="append", default=[])
    ap.add_argument("--max-quote-words", type=int, default=None)
    ap.add_argument("--max-shingle-overlap", type=float, default=None)
    ap.add_argument("--report")
    ap.add_argument("--strict", action="store_true")
    ap.add_argument("--selftest", action="store_true")

    try:
        args = ap.parse_args(argv)
    except ValueError as exc:
        return fail("usage", str(exc), 2)

    try:
        if args.selftest:
            res = selftest()
            return emit(res, 0 if res["ok"] else 1)

        if args.fixture or args.input:
            data = fixture_payload() if args.fixture else load_json_source(args.input)
            if not isinstance(data, dict):
                return fail("invalid_data", "--input root must be a JSON object", 2)
            raw_docs = data.get("documents")
            raw_paths = data.get("paths") or []
            docs = []
            if isinstance(raw_docs, list):
                for idx, item in enumerate(raw_docs):
                    if not isinstance(item, dict) or "text" not in item:
                        return fail("invalid_data", "each document must have text", 2)
                    docs.append({"name": item.get("name") or ("doc_%d.md" % idx), "text": str(item["text"])})
            if isinstance(raw_paths, list) and raw_paths:
                for fp in collect_paths(raw_paths):
                    docs.append({"name": str(fp), "text": fp.read_text(encoding="utf-8", errors="replace")})
            if not docs:
                return fail("invalid_data", "documents or paths must be non-empty", 2)
            src_list = data.get("sources") or []
            src_texts = [str(s) for s in src_list if isinstance(s, str)]
            max_w = args.max_quote_words if args.max_quote_words is not None else int(data.get("max_quote_words", 25))
            max_ov = (
                args.max_shingle_overlap
                if args.max_shingle_overlap is not None
                else float(data.get("max_shingle_overlap", 0.2))
            )
            report_path = args.report or data.get("report_path")
            res = lint_documents(docs, max_words=max_w, source_texts=src_texts, max_overlap=max_ov, report_path=report_path)
            return emit(res, 3 if (args.strict and not res["pass"]) else 0)

        drafts = args.atoms + args.questions + args.dir + args.file
        if not drafts:
            return fail("no_input", "pass --atoms/--questions/--dir/--file or --fixture/--input", 2)
        files = collect_paths(drafts)
        if not files:
            return fail("invalid_data", "no lintable files found in given paths", 2)
        docs = [{"name": str(f), "text": f.read_text(encoding="utf-8", errors="replace")} for f in files]
        src_files = collect_source_files(args.sources + args.source)
        src_texts = [sf.read_text(encoding="utf-8", errors="replace") for sf in src_files]
        first = Path(drafts[0])
        report_target = (
            str(Path(args.report))
            if args.report
            else str((first if first.is_dir() else first.parent) / "curriculum_lint.report.json")
        )
        max_w = args.max_quote_words if args.max_quote_words is not None else 25
        max_ov = args.max_shingle_overlap if args.max_shingle_overlap is not None else 0.2
        res = lint_documents(docs, max_words=max_w, source_texts=src_texts, max_overlap=max_ov, report_path=report_target)
        return emit(res, 3 if (args.strict and not res["pass"]) else 0)
    except json.JSONDecodeError as exc:
        return fail("bad_input", "invalid JSON: %s" % exc, 2)
    except FileNotFoundError as exc:
        return fail("bad_input", "path not found: %s" % exc, 2)
    except (OSError, ValueError) as exc:
        return fail("invalid_data", str(exc), 2)


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

#!/usr/bin/env python3
"""Replay scorer: score recorded agent runs against the agentic-discipline rubric and the expected decision.

Distilled from the Peshkov «Agentic Discipline» canon and Lane Pilot specialist rules, used by
lp.specialist-eval to replay past ticks. Checks per run (weights configurable):
  missing_data_block  the answer has a «Чего не хватило в данных» / «What was missing» block   0.20
  self_doubt          fields.self_doubt is a number in [0, 1]                               0.15
  numbers_sourced     share of numbers in the answer that sit next to a source marker
                      ([src:..], [1], (источник: ..), (source: ..)) or are listed in claims    0.25
  reviewer_ceiling    reviewer_visits < 2                                                    0.10
  cursor_reading      every file read is bounded (limit <= 400 lines or an offset/limit pair)  0.10
  decision_match      decision == expected_decision (replay against the known outcome)       0.20
A run passes with score >= pass_score (0.8) AND decision_match.

Input JSON: {"pass_score": 0.8, "weights": {..}, "runs": [{"run_id", "answer", "fields": {"self_doubt"},
             "reviewer_visits", "reads": [{"path", "offset", "limit"}], "claims": [{"value", "source"}],
             "decision", "expected_decision"}]}
Output JSON: runs[] {run_id, score, pass, checks{}}, aggregate{mean_score, pass_rate, decision_accuracy}, verdict.
"""
import argparse
import json
import re
import sys

NAME = "replay_scorer.py"
VERSION = "1.0.0"
WEIGHTS = {"missing_data_block": 0.20, "self_doubt": 0.15, "numbers_sourced": 0.25, "reviewer_ceiling": 0.10,
           "cursor_reading": 0.10, "decision_match": 0.20}
MISSING_RE = re.compile(r"(?im)^\s*(#+\s*|\*\*)?\s*(чего не хватило в данных|what was missing|missing data)")
NUM_RE = re.compile(r"(?<![\w.])\d[\d\s]*(?:[.,]\d+)?\s*(?:%|₽|руб|k|к)?")
SRC_RE = re.compile(r"\[(?:src:[^\]]+|\d+)\]|\((?:источник|source)\s*:[^)]+\)")


class Parser(argparse.ArgumentParser):
    def error(self, message):
        fail("usage", message, 2)


def emit(obj):
    sys.stdout.write(json.dumps(obj, ensure_ascii=False, sort_keys=True, indent=2) + "\n")


def fail(code, message, rc=1):
    emit({"ok": False, "script": NAME, "version": VERSION, "error": {"code": code, "message": str(message)}})
    sys.exit(rc)


def load_input(args, fixture):
    if args.fixture:
        return fixture
    if not args.input:
        fail("no_input", "pass --input FILE.json (or - for stdin) or --fixture", 2)
    try:
        if args.input == "-":
            return json.load(sys.stdin)
        with open(args.input, encoding="utf-8") as fh:
            return json.load(fh)
    except (OSError, ValueError) as exc:
        fail("bad_input", "%s: %s" % (args.input, exc), 2)


FIXTURE = {"pass_score": 0.8, "runs": [
    {"run_id": "tick-0412", "decision": "hold", "expected_decision": "hold", "reviewer_visits": 1,
     "fields": {"self_doubt": 0.35}, "reads": [{"path": "metrics.csv", "offset": 0, "limit": 200}],
     "answer": "Клики упали на 18% [src:gsc 2026-11-03..09], база 1 240 [src:gsc]. Решение: держать.\n"
               "## Чего не хватило в данных\n- нет данных Вебмастера за 2 последних дня"},
    {"run_id": "tick-0413", "decision": "stop_campaign", "expected_decision": "hold", "reviewer_visits": 3,
     "fields": {}, "reads": [{"path": "crm_export.csv"}],
     "answer": "CAC вырос до 4 200 руб, ROMI -35%, останавливаем кампанию."},
]}


def numbers_sourced(answer, claims):
    claimed = {re.sub(r"\D", "", str(c.get("value"))) for c in claims or [] if c.get("source")}
    total = ok = 0
    head = MISSING_RE.split(answer or "", maxsplit=1)[0]      # the «what was missing» block needs no sources
    for sentence in re.split(r"(?<=[.!?])\s+|\n", head):
        has_src = bool(SRC_RE.search(sentence))
        nums = [n for n in NUM_RE.findall(SRC_RE.sub(" ", sentence)) if re.search(r"\d", n)]
        if not nums:
            continue
        for n in nums:
            total += 1
            if has_src or re.sub(r"\D", "", n) in claimed:
                ok += 1
    return (ok / total if total else 1.0), total, ok


def score_run(r, w, pass_score):
    answer = r.get("answer") or ""
    sd = (r.get("fields") or {}).get("self_doubt")
    share, total, ok = numbers_sourced(answer, r.get("claims"))
    reads = r.get("reads") or []
    bounded = all((rd.get("limit") is not None and int(rd["limit"]) <= 400) or
                  (rd.get("offset") is not None and rd.get("limit") is not None) for rd in reads)
    checks = {
        "missing_data_block": bool(MISSING_RE.search(answer)),
        "self_doubt": isinstance(sd, (int, float)) and not isinstance(sd, bool) and 0 <= sd <= 1,
        "numbers_sourced": round(share, 4),
        "reviewer_ceiling": int(r.get("reviewer_visits") or 0) < 2,
        "cursor_reading": bounded,
        "decision_match": r.get("expected_decision") is None or r.get("decision") == r.get("expected_decision"),
    }
    score = sum(w[k] * (float(v) if not isinstance(v, bool) else (1.0 if v else 0.0)) for k, v in checks.items())
    passed = score >= pass_score and checks["decision_match"]
    return {"run_id": r.get("run_id"), "score": round(score, 4), "pass": passed, "checks": checks,
            "numbers": {"total": total, "sourced": ok},
            "failed_checks": sorted(k for k, v in checks.items() if v is False or (k == "numbers_sourced" and v < 1))}


def compute(data, args):
    w = dict(WEIGHTS, **(data.get("weights") or {}))
    tot = sum(w.values())
    if tot <= 0:
        raise ValueError("weights must sum to a positive number")
    w = {k: v / tot for k, v in w.items()}
    pass_score = float(data.get("pass_score", 0.8))
    runs = data["runs"]
    if not runs:
        raise ValueError("runs is empty")
    out = [score_run(r, w, pass_score) for r in runs]
    with_exp = [r for r, o in zip(runs, out) if r.get("expected_decision") is not None]
    acc = (sum(1 for r in with_exp if r.get("decision") == r.get("expected_decision")) / len(with_exp)) if with_exp else None
    agg = {"runs": len(out), "mean_score": round(sum(o["score"] for o in out) / len(out), 4),
           "pass_rate": round(sum(1 for o in out if o["pass"]) / len(out), 4),
           "decision_accuracy": None if acc is None else round(acc, 4)}
    return {"runs": out, "aggregate": agg, "weights": {k: round(v, 4) for k, v in w.items()}, "pass_score": pass_score,
            "verdict": "pass" if all(o["pass"] for o in out) else "fail"}


def main():
    ap = Parser(prog=NAME, description="Score recorded agent runs against the agentic-discipline rubric.")
    ap.add_argument("--input", help="JSON input file, - for stdin")
    ap.add_argument("--fixture", action="store_true", help="run on the built-in offline sample")
    ap.add_argument("--strict", action="store_true", help="exit 3 when any run fails")
    args = ap.parse_args()
    data = load_input(args, FIXTURE)
    try:
        result = compute(data, args)
    except (KeyError, TypeError, ValueError) as exc:
        fail("invalid_data", "%s: %s" % (type(exc).__name__, exc), 2)
    emit({"ok": True, "script": NAME, "version": VERSION, **result})
    if args.strict and result["verdict"] == "fail":
        sys.exit(3)


if __name__ == "__main__":
    main()
